// ProcessPayment charges the given amount and records the transaction.
func ProcessPayment(userID string, amountCents int64) (*Receipt, error) {
	if amountCents <= 0 {
		return nil, ErrInvalidAmount
	}
	account, err := lookupAccount(userID)
	if err != nil {
		return nil, err
	}
	accountMu.Lock()
	defer accountMu.Unlock()
	tx := beginTransaction(account, amountCents)
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return &Receipt{TxID: tx.ID, AmountCents: amountCents}, nil
}
